use crate::{generation::*,read_selection::*,roots::{Binding,Identity}};
use std::collections::BTreeMap;

fn binding(root:&str,path:&str,raw:&[u8])->Binding {Binding{kind:"execution".into(),root_id:root.into(),relative_path:path.into(),sha256:crate::roots::hash(raw),size_bytes:raw.len() as u64}}
fn sample()->(StoreSelection,Vec<u8>,Binding,Vec<u8>,Binding,Vec<u8>,Consumer,Binding){
    let adapter=binding("config","adapter",b"adapter");
    let member=MemberRole{original_identity:"native-journal".into(),relative_path:"native/journal".into(),semantic_role:"journal".into(),writer_adapter:adapter.clone(),reader_adapters:vec![adapter.clone()],commit_interpretation:"generation-pointer-v1".into()};
    let consumer=Consumer{original_identity:"replay".into(),adapter,member_paths:vec!["native/journal".into()],commit_interpretation:"generation-pointer-v1".into()};
    let members=vec![member];let consumers=vec![consumer.clone()];
    let store=StoreSelection{schema_version:"lab-generation-store/v2".into(),store_id:"store".into(),instance_id:"instance".into(),writer_domain:"writer".into(),pointer_root_id:"generation".into(),pointer_member:"CURRENT".into(),generations_root_id:"generation".into(),control_root_id:"control".into(),control_root_binding:binding("config","control",b"c"),member_inventory:members.clone(),consumer_inventory:consumers.clone(),filesystem_profile:binding("config","fs",b"f"),schema_binding:binding("config","schema",b"s"),codec_binding:binding("config","codec",b"j"),limits:Limits{max_member_bytes:4096,max_members:1,max_stage_bytes:4096,retained_generation_bytes:4096,retained_generation_count:1,retained_orphan_bytes:4096,retained_orphan_count:1,journal_reserve_bytes:32*4096+12*4096,journal_reserve_inodes:46,max_record_bytes:4096,max_repair_record_bytes:4096,in_flight:1,verifier_timeout_ms:1000,max_verifier_result_bytes:4096},c01_selection_binding:binding("config","c01",b"c01"),canonical_member_inventory_binding:binding("config","members",&canonical(&members).unwrap()),commit_interpretation_binding:binding("config","interpretation",b"i"),c01_transport_limits:TransportLimits{max_frame_bytes:4096,lock_timeout_ms:1000,rpc_timeout_ms:1000,phase_timeout_ms:1000}};
    assert!(store.validate().is_ok());
    let member_binding=binding("generation","gen-1/native/journal",b"original");
    let manifest=GenerationManifest{schema_version:"lab-generation-manifest/v1".into(),store_id:"store".into(),creation_instance:"instance".into(),writer_epoch:1,sequence:1,generation_id:"gen-1".into(),predecessor_pointer_binding:None,operation_id:"op".into(),original_fingerprint:"a".repeat(64),stage_creation_binding:binding("config","stage",b"stage"),member_manifest_binding:binding("config","native-manifest",b"n"),stage_identity:Identity{device:1,inode:1,mount_id:1,uid:1,gid:1,mode:0o700},members:BTreeMap::from([("native/journal".into(),member_binding)]),original_cut_binding:binding("config","cut",b"cut"),source_cut:"cut-1".into(),reader_inventory_binding:binding("config","readers",&canonical(&consumers).unwrap()),expected_replay_result_binding:binding("config","expectation",b"e")};
    let rich=canonical(&manifest).unwrap();let rich_binding=binding("journal","commit-op/manifest.json",&rich);
    let c01=c01_manifest(&manifest).unwrap();let c01_binding=binding("journal","commit-op/c01-manifest.json",&c01);
    let pointer=PointerRecord{schema_version:"lab-completion-pointer-record/v1".into(),logical_store_id:"store".into(),writer_epoch:1,sequence:1,predecessor_pointer_binding:None,generation_manifest_binding:c01_binding,operation_id:"op".into()};
    let pointer_raw=canonical(&pointer).unwrap();let pointer_binding=binding("generation","CURRENT",&pointer_raw);
    let disclosure=binding("config","disclosure",b"grant");
    (store,pointer_raw,pointer_binding,rich,rich_binding,c01,consumer,disclosure)
}
fn joined(input:&(StoreSelection,Vec<u8>,Binding,Vec<u8>,Binding,Vec<u8>,Consumer,Binding))->crate::roots::Result<ReadJoin>{join_originals(&input.0,&input.1,&input.2,&input.3,&input.4,&input.5,&input.6,&input.7)}
#[test] fn pins_originals_across_later_pointer_and_checks_member_bytes(){let input=sample();let pinned=joined(&input).unwrap();assert_eq!(pinned.sequence,1);assert!(pinned.check_member(&input.6,"native/journal",b"original").is_ok());let mut later=input.1.clone();later.push(b' ');assert!(join_originals(&input.0,&later,&input.2,&input.3,&input.4,&input.5,&input.6,&input.7).is_err());assert!(pinned.check_member(&input.6,"native/journal",b"original").is_ok());}
#[test] fn refuses_tampered_member_and_wrong_consumer(){let input=sample();let pinned=joined(&input).unwrap();assert_eq!(pinned.check_member(&input.6,"native/journal",b"changed").unwrap_err().0,"READ_MEMBER_BYTES");let mut wrong=input.6.clone();wrong.adapter=binding("config","other",b"other");assert_eq!(pinned.check_member(&wrong,"native/journal",b"original").unwrap_err().0,"READ_MEMBER_PERMISSION");}
#[test] fn refuses_forged_consumer_with_same_adapter(){let input=sample();let pinned=joined(&input).unwrap();let mut wrong=input.6.clone();wrong.original_identity="other".into();assert_eq!(pinned.check_member(&wrong,"native/journal",b"original").unwrap_err().0,"READ_MEMBER_PERMISSION");let mut wrong=input.6.clone();wrong.member_paths.push("other".into());assert_eq!(pinned.check_member(&wrong,"native/journal",b"original").unwrap_err().0,"READ_MEMBER_PERMISSION");}
#[test] fn refuses_projection_and_omitted_member(){let mut input=sample();input.5=b"{}".to_vec();assert_eq!(joined(&input).unwrap_err().0,"READ_MANIFEST_PROJECTION");let mut input=sample();let mut manifest:GenerationManifest=serde_json::from_slice(&input.3).unwrap();manifest.members.clear();input.3=canonical(&manifest).unwrap();input.4=binding("journal","commit-op/manifest.json",&input.3);input.5=c01_manifest(&manifest).unwrap();let mut pointer:PointerRecord=serde_json::from_slice(&input.1).unwrap();pointer.generation_manifest_binding=binding("journal","commit-op/c01-manifest.json",&input.5);input.1=canonical(&pointer).unwrap();input.2=binding("generation","CURRENT",&input.1);assert_eq!(joined(&input).unwrap_err().0,"READ_CONSUMER_COVERAGE");}
#[test] fn refuses_unbound_pointer_and_disclosure(){let mut input=sample();input.2.sha256="b".repeat(64);assert_eq!(joined(&input).unwrap_err().0,"READ_ORIGINAL_BINDING");let mut input=sample();input.7.sha256="bad".into();assert_eq!(joined(&input).unwrap_err().0,"READ_BINDING");}
